class Command(BaseCommand):
    help = "Seed fresher-friendly interview questions and sample answers."

    def handle(self, *args, **options):
        created = updated = 0
        for category, question, answer, tips, keywords in QUESTIONS:
            _, was_created = InterviewQuestion.objects.update_or_create(
                category=category,
                question_text=question,
                defaults={
                    "sample_answer": answer,
                    "answer_tips": tips,
                    "keywords": keywords,
                    "is_active": True,
                },
            )
            if was_created:
                created += 1
            else:
                updated += 1
        self.stdout.write(self.style.SUCCESS(
            f"Interview bank ready: {created} created, {updated} updated, "
            f"{InterviewQuestion.objects.filter(is_active=True).count()} active questions."
        ))
